from pathlib import Path
import json, html
P=Path(__file__).resolve().parent
R=json.loads((P/'projection-results.json').read_text())
B=R['base']; U=R['upside']; D=R['downside']
def money(n,compact=False):
    sign='−' if n<0 else ''
    n=abs(n)
    return sign+(f'${n/1000000:.2f}m' if compact and n>=1000000 else f'${n/1000:,.0f}k' if compact and n>=1000 else f'${n:,.0f}')
def num(n):return f'{n:,.0f}'
def table(headers,rows,compact=False):
    return '<div class="table-wrap"><table class="matrix '+('compact ' if compact else '')+'"><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def panel(title,text,cls=''):return f'<div class="panel {cls}"><h3>{title}</h3>{text}</div>'
def evidence(text):return '<div class="evidence">'+text+'</div>'
def link(label,url):return f'<a href="{html.escape(url)}" target="_blank" rel="noopener">{label}</a>'
