page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Patina — The maker’s reason to pay</title><meta name="description" content="Customer evidence, pricing tests, seller returns and 36-month scenarios for Patina furniture commerce."><style>'''+css+'''</style></head><body><header class="top"><div class="wordmark">patina</div><div class="meta">Furniture commerce · Research and business case · October 2026</div><div class="actions"><button id="overviewButton" aria-controls="overview" aria-expanded="false">All slides</button><button id="notesButton" aria-controls="notes" aria-expanded="false">Notes N</button><button id="printButton">Print / PDF</button></div></header><main id="deck" aria-label="Furniture commerce research presentation">'''+''.join(sections)+'''</main><footer class="footer"><div class="label" id="chapter"></div><div class="nav"><button id="previous" aria-label="Previous slide">←</button><span class="count" id="counter" aria-live="polite"></span><button id="next" aria-label="Next slide">→</button></div></footer><aside id="notes" class="notes" aria-label="Presenter notes" hidden><button id="closeNotes" class="close" aria-label="Close notes">×</button><h2>Presenter notes</h2><p id="notesText"></p><p class="small">← → navigate · N notes · O overview · Home / End · Esc close</p></aside><div id="overview" class="overview" role="dialog" aria-modal="true" aria-labelledby="overviewTitle" hidden><div class="overview-inner"><header><h2 id="overviewTitle">The business case</h2><button id="closeOverview">Close</button></header><div class="overview-grid" id="overviewGrid"></div></div></div><div id="announcement" class="sr-only" aria-live="polite"></div><script>'''+js+'''</script></body></html>'''
